import{_ as o,r as t,o as l,c as r,e as s,a as i,s as p}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Blueprints - October CMS - 4.x","titleTemplate":false,"description":"The template structure for your website content.","frontmatter":{"subtitle":"The template structure for your website content."},"headers":[{"level":2,"title":"Entry","slug":"entry","link":"#entry","children":[{"level":3,"title":"Entry Variants","slug":"entry-variants","link":"#entry-variants","children":[{"level":4,"title":"Single Entries","slug":"single-entries","link":"#single-entries","children":[]},{"level":4,"title":"Structure Entries","slug":"structure-entries","link":"#structure-entries","children":[]},{"level":4,"title":"Stream Entries","slug":"stream-entries","link":"#stream-entries","children":[]}]},{"level":3,"title":"Content Groups","slug":"content-groups","link":"#content-groups","children":[]},{"level":3,"title":"Custom Messages","slug":"custom-messages","link":"#custom-messages","children":[]},{"level":3,"title":"Disabling Required Fields","slug":"disabling-required-fields","link":"#disabling-required-fields","children":[]},{"level":3,"title":"Page Finder Configuration","slug":"page-finder-configuration","link":"#page-finder-configuration","children":[]},{"level":3,"title":"Custom Permissions","slug":"custom-permissions","link":"#custom-permissions","children":[]}]},{"level":2,"title":"Submission","slug":"submission","link":"#submission","children":[{"level":3,"title":"Moderation Workflow","slug":"moderation-workflow","link":"#moderation-workflow","children":[]},{"level":3,"title":"Multi-Step Fields","slug":"multi-step-fields","link":"#multi-step-fields","children":[]},{"level":3,"title":"Record Titles","slug":"record-titles","link":"#record-titles","children":[]},{"level":3,"title":"Email Notifications","slug":"email-notifications","link":"#email-notifications","children":[]}]},{"level":2,"title":"Global","slug":"global","link":"#global","children":[]},{"level":2,"title":"Mixin","slug":"mixin","link":"#mixin","children":[{"level":3,"title":"Using the Mixin","slug":"using-the-mixin","link":"#using-the-mixin","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}]}],"relativePath":"4.x/cms/tailor/blueprints.md","filePath":"4.x/cms/tailor/blueprints.md"}'),c={name:"4.x/cms/tailor/blueprints.md"};function d(u,e,g,h,m,k){const n=t("pre-heading"),a=t("post-heading");return l(),r("div",null,[s(n),e[0]||(e[0]=i("h1",null,"Blueprints",-1)),s(a),e[1]||(e[1]=p(`<h2 id="entry"><a href="#entry" class="header-anchor">#</a> Entry</h2><p>An entry blueprint is the standard content structure used to define areas of your website. The content structures and entries can be organised in different ways as we describe in more detail here.</p><p>The <code>entry</code> type supports multiple entries and should be used when no other variant applies.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">handle</span><span class="token punctuation">:</span> Team\\Member
<span class="token key atrule">type</span><span class="token punctuation">:</span> entry
<span class="token key atrule">name</span><span class="token punctuation">:</span> Team Member

<span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">name</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> First Name
        <span class="token key atrule">type</span><span class="token punctuation">:</span> text
</code></pre></div><p>The following properties are supported by the entry blueprint.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>handle</strong></td><td>A meaningful and unique code to identify the entry.</td></tr><tr><td><strong>type</strong></td><td>The blueprint type which can be a variant of <code>entry</code>, <code>single</code>, <code>structure</code> or <code>stream</code>.</td></tr><tr><td><strong>name</strong></td><td>The label to display when working with this entry.</td></tr><tr><td><strong>fields</strong></td><td>form fields belonging to the group, see <a href="./../../element/form-fields.html">backend form fields</a>.</td></tr><tr><td><strong>groups</strong></td><td>references a group of form fields placing the entry in group mode (see below).</td></tr><tr><td><strong>structure</strong></td><td>structure configuration supplied when using the <code>structure</code> type.</td></tr><tr><td><strong>drafts</strong></td><td>enables drafts for this entry. Default: <code>false</code></td></tr><tr><td><strong>softDeletes</strong></td><td>enables soft deletion for this entry. Default: <code>true</code></td></tr><tr><td><strong>multisite</strong></td><td>enables multisite for this entry, sync records between group, locale or all sites. Supported values: <code>true</code>, <code>false</code>, <code>sync</code>, <code>locale</code>, <code>all</code>. Default: <code>false</code></td></tr><tr><td><strong>pagefinder</strong></td><td>includes blueprint type in the <a href="./../../element/form/widget-pagefinder.html">pagefinder form widget</a>, supported values: <code>true</code>, <code>false</code>, <code>item</code>, <code>list</code> or array (see below). Default: <code>true</code></td></tr><tr><td><strong>defaultSort</strong></td><td>used by the <code>entry</code> and <code>stream</code> types, sets a default sorting column and direction when user preference is not defined. Supports a string or an array with keys <code>column</code> and <code>direction</code>. The direction can be <code>asc</code> for ascending (default) or <code>desc</code> for descending order.</td></tr><tr><td><strong>customMessages</strong></td><td>customize the messages used in the user interface (see below).</td></tr><tr><td><strong>showExport</strong></td><td>displays a toolbar button for exporting records. Default: <code>true</code>.</td></tr><tr><td><strong>showImport</strong></td><td>displays a toolbar button for importing records. Default: <code>true</code>.</td></tr><tr><td><strong>modelClass</strong></td><td>replaces the PHP model class with a <a href="./models.html">custom model instance</a>.</td></tr><tr><td><strong>permissions</strong></td><td>customize the permission <code>code</code> and <code>label</code> registered for this blueprint (see below).</td></tr></tbody></table></div><h3 id="entry-variants"><a href="#entry-variants" class="header-anchor">#</a> Entry Variants</h3><p>While an entry type has no specific behavior, there are also several variants that can be used for organizing content. The following types are variants of an entry.</p><ul><li><strong>entry</strong> is a basic entry for common purposes.</li><li><strong>single</strong> is a single entry with dedicated fields, eg: Contact Us Page.</li><li><strong>structure</strong> is a defined structure of entries, eg: Documentation Pages.</li><li><strong>stream</strong> is a stream of time stamped entries, eg: Blog Posts.</li></ul><h4 id="single-entries"><a href="#single-entries" class="header-anchor">#</a> Single Entries</h4><p>The <code>single</code> type will force a single entry for each section definition. This is useful for one-off content, such as a Home page or Contact Us page. The following defines a <strong>Homepage</strong> section with a Welcome Message (<code>welcome_message</code>) text field.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">handle</span><span class="token punctuation">:</span> Homepage
<span class="token key atrule">type</span><span class="token punctuation">:</span> single
<span class="token key atrule">name</span><span class="token punctuation">:</span> Homepage Content

<span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">welcome_message</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Welcome Message
        <span class="token key atrule">type</span><span class="token punctuation">:</span> text
</code></pre></div><h4 id="structure-entries"><a href="#structure-entries" class="header-anchor">#</a> Structure Entries</h4><p>The <code>structure</code> type allows multiple structured entries, allowing for parent-child relationships to exist. This is useful for nested content, such as a Documentation section. Entries of the type <code>structure</code> are sortable. Their sort order can be adjusted by dragging them in the list view. The following defines a <strong>Documentation</strong> tree section with an Article Content (<code>article_content</code>) markdown field.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">handle</span><span class="token punctuation">:</span> Docs\\Article
<span class="token key atrule">type</span><span class="token punctuation">:</span> structure
<span class="token key atrule">name</span><span class="token punctuation">:</span> Documentation Article

<span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">content</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Article Content
        <span class="token key atrule">type</span><span class="token punctuation">:</span> markdown
</code></pre></div><p>By default structures support unlimited nesting, however, you may specify a maximum depth for the tree using <code>maxDepth</code> in the <code>structure</code> property. In the next example there can only be a top level and a second level.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># ...</span>
<span class="token key atrule">type</span><span class="token punctuation">:</span> structure

<span class="token key atrule">structure</span><span class="token punctuation">:</span>
    <span class="token key atrule">maxDepth</span><span class="token punctuation">:</span> <span class="token number">2</span>
    <span class="token comment"># ...</span>
</code></pre></div><p>The following values are supported by the <code>structure</code> property.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>maxDepth</strong></td><td>Maximum depth for the structure. Default: <code>0</code> for unlimited.</td></tr><tr><td><strong>treeExpanded</strong></td><td>if tree nodes should be expanded by default. Default: <code>true</code></td></tr><tr><td><strong>showReorder</strong></td><td>displays an interface for reordering records. Default: <code>true</code></td></tr><tr><td><strong>showSorting</strong></td><td>allows sorting records, disables the structure when sorted. Default: <code>true</code></td></tr></tbody></table></div><h4 id="stream-entries"><a href="#stream-entries" class="header-anchor">#</a> Stream Entries</h4><p>The <code>stream</code> type is used for time-based entries that are often listed in chronological order. This is useful for publishing recent activity, such as a Blog section. The following defines a <strong>Blog</strong> feed section with a Post Content (<code>content</code>) rich editor field.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">handle</span><span class="token punctuation">:</span> Blog\\Post
<span class="token key atrule">type</span><span class="token punctuation">:</span> stream
<span class="token key atrule">name</span><span class="token punctuation">:</span> Blog Post

<span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">content</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Post Content
        <span class="token key atrule">type</span><span class="token punctuation">:</span> richeditor
</code></pre></div><p>The <code>defaultSort</code> property is used to set the default sorting column when the blueprint record is displayed as a list. This will be set to the published date by default.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">handle</span><span class="token punctuation">:</span> Blog\\Post
<span class="token key atrule">type</span><span class="token punctuation">:</span> stream
<span class="token key atrule">name</span><span class="token punctuation">:</span> Blog Post

<span class="token key atrule">defaultSort</span><span class="token punctuation">:</span>
    <span class="token key atrule">column</span><span class="token punctuation">:</span> title
    <span class="token key atrule">direction</span><span class="token punctuation">:</span> asc
</code></pre></div><h3 id="content-groups"><a href="#content-groups" class="header-anchor">#</a> Content Groups</h3><p>All entries optionally support the ability to define multiple content groups for a section. For example, a blog section may have a regular post and a featured post, and these are two entry groups.</p><p>Entry groups are defined by the <strong>groups</strong> property in the section blueprint file and different <strong>fields</strong> can be specified for each type. The selected group value is available as the <code>content_group</code> attribute on the record.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">handle</span><span class="token punctuation">:</span> Blog\\Post
<span class="token key atrule">type</span><span class="token punctuation">:</span> stream
<span class="token key atrule">name</span><span class="token punctuation">:</span> Blog Post

<span class="token key atrule">groups</span><span class="token punctuation">:</span>
    <span class="token key atrule">regular_post</span><span class="token punctuation">:</span>
        <span class="token key atrule">name</span><span class="token punctuation">:</span> Regular Post
        <span class="token key atrule">fields</span><span class="token punctuation">:</span>
            <span class="token comment"># ...</span>

    <span class="token key atrule">featured_post</span><span class="token punctuation">:</span>
        <span class="token key atrule">name</span><span class="token punctuation">:</span> Featured Post
        <span class="token key atrule">fields</span><span class="token punctuation">:</span>
            <span class="token comment"># ...</span>
</code></pre></div><div class="custom-block tip"><p>It is recommended to use <a href="#mixin">mixin blueprints</a> to group common field definitions.</p></div><h3 id="custom-messages"><a href="#custom-messages" class="header-anchor">#</a> Custom Messages</h3><p>Specify the <code>customMessages</code> property to override the default messages used by the interface. The values can be plain text or can refer to a <a href="./../../extend/multisite/localization.html">localization string</a>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">customMessages</span><span class="token punctuation">:</span>
    <span class="token key atrule">buttonCreate</span><span class="token punctuation">:</span> Create New Event
</code></pre></div><p>The following messages are available to override as custom messages.</p><details class="custom-block details"><summary>View the list of available messages</summary><div class="table"><table tabindex="0"><thead><tr><th>Message</th><th>Default Message</th></tr></thead><tbody><tr><td><strong>buttonCreate</strong></td><td>Create :name Entry</td></tr><tr><td><strong>titleIndexList</strong></td><td>Manage :name Entries</td></tr><tr><td><strong>titleCreateForm</strong></td><td>Create :name</td></tr><tr><td><strong>titleUpdateForm</strong></td><td>Update :name</td></tr><tr><td><strong>pagefinderItemType</strong></td><td>:name Entry</td></tr><tr><td><strong>pagefinderListType</strong></td><td>All :name Entries</td></tr></tbody></table></div></details><h3 id="disabling-required-fields"><a href="#disabling-required-fields" class="header-anchor">#</a> Disabling Required Fields</h3><p>The entry record will require the <code>title</code> and <code>slug</code> fields to be populated before they can be saved, additionally, the <code>slug</code> field must also be unique. You may modify this functionality by overriding these fields in your blueprint. Either by setting the <code>validation</code> property to <strong>false</strong> or setting the <code>hidden</code> property to <strong>true</strong> and hiding it from the user interface. The following example will disable the validation for both fields and hide the slug field.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span>
        <span class="token key atrule">validation</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>

    <span class="token key atrule">slug</span><span class="token punctuation">:</span>
        <span class="token key atrule">hidden</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><h3 id="page-finder-configuration"><a href="#page-finder-configuration" class="header-anchor">#</a> Page Finder Configuration</h3><p>By default, all entries are included in the <a href="./../../element/form/widget-pagefinder.html">page finder</a> lookup values. This can be disabled by setting the <strong>pagefinder</strong> to <code>false</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">pagefinder</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><p>You may restrict the page finder context to only allow locating the page as a single <code>item</code> (e.g. Blog Post) or a <code>list</code> of items (e.g. All Blog Posts), or when set to <code>all</code> will display both.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">pagefinder</span><span class="token punctuation">:</span> item
<span class="token key atrule">pagefinder</span><span class="token punctuation">:</span> list
</code></pre></div><p>The page finder will automatically resolve the <code>id</code>, <code>code</code>, <code>slug</code> and <code>fullslug</code> attributes and use them as replacements in the <a href="./../themes/pages.html">page URL parameters</a>. You may specify custom <strong>replacements</strong> as an array using the <strong>pagefinder</strong> properties, including the optional <strong>context</strong> from above.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">pagefinder</span><span class="token punctuation">:</span>
    <span class="token key atrule">context</span><span class="token punctuation">:</span> list
    <span class="token key atrule">replacements</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>
</code></pre></div><p>Each replacement key should match a URL parameter name and use a dot notation path to the attribute value. Take the following URL example for a blog post page.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/post/:author/:category/:slug/:id</span>&quot;</span>
</code></pre></div><p>The following <strong>replacements</strong> will set the <code>:author</code> parameter to the related author slug attribute value, and the <code>:category</code> parameter to the first related categories slug attribute value.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">pagefinder</span><span class="token punctuation">:</span>
    <span class="token key atrule">replacements</span><span class="token punctuation">:</span>
        <span class="token key atrule">author</span><span class="token punctuation">:</span> author.slug
        <span class="token key atrule">category</span><span class="token punctuation">:</span> categories.0.slug
</code></pre></div><h3 id="custom-permissions"><a href="#custom-permissions" class="header-anchor">#</a> Custom Permissions</h3><p>Every blueprint registers permissions in the admin panel, and by default the permission code is based on the blueprint UUID and the label is based on the blueprint name. When multiple blueprints share the same name, the <code>permissions</code> property is used to make them easier to identify.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">name</span><span class="token punctuation">:</span> Tag
<span class="token key atrule">handle</span><span class="token punctuation">:</span> Blog\\Tag

<span class="token key atrule">permissions</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Blog Tags
</code></pre></div><p>Specify a custom <code>code</code> to give the permission a readable code, this can also be used to share a single permission definition between multiple blueprints by giving them the same code.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">permissions</span><span class="token punctuation">:</span>
    <span class="token key atrule">code</span><span class="token punctuation">:</span> blog_tags
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Blog Tags
</code></pre></div><p>The following values are supported by the <code>permissions</code> property.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>code</strong></td><td>a custom permission code used in place of the blueprint UUID.</td></tr><tr><td><strong>label</strong></td><td>a custom label to display in the permissions editor.</td></tr></tbody></table></div><h2 id="submission"><a href="#submission" class="header-anchor">#</a> Submission</h2><p>A submission blueprint is used to accept user generated content from the frontend of your website, such as blog comments, contact form submissions or product reviews. Submissions are captured on the frontend using the <a href="./../components/submission.html">submission component</a> and moderated in the admin panel.</p><p>The following defines a <strong>Comment</strong> submission with Name (<code>author_name</code>), Email Address (<code>author_email</code>) and Comment (<code>content</code>) fields, along with a reference to the blog post (<code>post</code>) being commented on.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">handle</span><span class="token punctuation">:</span> Blog\\Comment
<span class="token key atrule">type</span><span class="token punctuation">:</span> submission
<span class="token key atrule">name</span><span class="token punctuation">:</span> Comment

<span class="token key atrule">submission</span><span class="token punctuation">:</span>
    <span class="token key atrule">titleTemplate</span><span class="token punctuation">:</span> <span class="token string">&#39;{{ str_limit(content, 60) }}&#39;</span>

<span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">author_name</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Name
        <span class="token key atrule">type</span><span class="token punctuation">:</span> text
        <span class="token key atrule">validation</span><span class="token punctuation">:</span> required<span class="token punctuation">|</span>min<span class="token punctuation">:</span>2<span class="token punctuation">|</span>max<span class="token punctuation">:</span><span class="token number">100</span>

    <span class="token key atrule">author_email</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Email Address
        <span class="token key atrule">type</span><span class="token punctuation">:</span> email
        <span class="token key atrule">validation</span><span class="token punctuation">:</span> required<span class="token punctuation">|</span>email

    <span class="token key atrule">content</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Comment
        <span class="token key atrule">type</span><span class="token punctuation">:</span> textarea
        <span class="token key atrule">validation</span><span class="token punctuation">:</span> required<span class="token punctuation">|</span>min<span class="token punctuation">:</span>5<span class="token punctuation">|</span>max<span class="token punctuation">:</span><span class="token number">2000</span>

    <span class="token key atrule">post</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Post
        <span class="token key atrule">type</span><span class="token punctuation">:</span> entries
        <span class="token key atrule">source</span><span class="token punctuation">:</span> Blog\\Post
        <span class="token key atrule">maxItems</span><span class="token punctuation">:</span> <span class="token number">1</span>
</code></pre></div><p>The following properties are supported by the submission blueprint.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>handle</strong></td><td>A meaningful and unique code to identify the entry.</td></tr><tr><td><strong>type</strong></td><td>set to <code>submission</code> for this blueprint type.</td></tr><tr><td><strong>name</strong></td><td>The label to display when working with this entry.</td></tr><tr><td><strong>fields</strong></td><td>form fields belonging to the group, see <a href="./../../element/form-fields.html">backend form fields</a>.</td></tr><tr><td><strong>submission</strong></td><td>submission configuration supplied for this type (see below).</td></tr></tbody></table></div><p>The following values are supported by the <code>submission</code> property.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>titleTemplate</strong></td><td>a Twig template used to build the record title (see below).</td></tr><tr><td><strong>notifyGroup</strong></td><td>an admin user group code to notify by email when a submission is received (see below).</td></tr><tr><td><strong>notifyTemplate</strong></td><td>the mail template used for the notification. Default: <code>tailor:submission-notification</code></td></tr><tr><td><strong>notifyReplyTo</strong></td><td>field name used as the reply-to address for the notification. Default: <code>email</code></td></tr><tr><td><strong>spamSweepDays</strong></td><td>lookback window in days used when marking a record as spam, where other pending submissions from the same IP address are also rejected. Use <code>0</code> to disable the sweep. Default: <code>30</code></td></tr><tr><td><strong>purgeRejectedDays</strong></td><td>number of days to keep rejected submissions before they are deleted forever. Use <code>0</code> to disable purging. Default: <code>30</code></td></tr></tbody></table></div><div class="custom-block warning"><p>Every field defined on a submission blueprint accepts user input from the frontend, so only define fields that visitors are allowed to populate.</p></div><h3 id="moderation-workflow"><a href="#moderation-workflow" class="header-anchor">#</a> Moderation Workflow</h3><p>Submissions arrive with a <strong>Pending</strong> status and are hidden from the frontend until they are approved. The admin panel provides <strong>Approve</strong> and <strong>Reject</strong> buttons for moderating records, where rejected submissions are soft deleted and can be restored at any time.</p><p>The <strong>Spam</strong> button rejects the selected records and also rejects other pending submissions received from the same IP address within the <code>spamSweepDays</code> window. Submissions that have already been approved are never affected by the sweep.</p><p>Rejected submissions are deleted forever after the <code>purgeRejectedDays</code> retention period has passed. This clean up happens automatically when viewing the submissions list in the admin panel.</p><p>Every submission automatically captures the visitor IP address and user agent in the <code>submitted_ip</code> and <code>submitted_user_agent</code> attributes. These are available as a list column, a filter scope and as read-only fields when viewing the record.</p><h3 id="multi-step-fields"><a href="#multi-step-fields" class="header-anchor">#</a> Multi-Step Fields</h3><p>Fields on a submission blueprint can be assigned to a step using the <code>tags</code> property, which accepts a single tag or an array of tags. This groups fields so they can be captured across several steps by a <a href="./../components/submission.html#multi-step-forms">multi-step submission form</a>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">rating</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Rating
        <span class="token key atrule">type</span><span class="token punctuation">:</span> dropdown
        <span class="token key atrule">validation</span><span class="token punctuation">:</span> required
        <span class="token key atrule">tags</span><span class="token punctuation">:</span> step1

    <span class="token key atrule">comments</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Comments
        <span class="token key atrule">type</span><span class="token punctuation">:</span> textarea
        <span class="token key atrule">validation</span><span class="token punctuation">:</span> required<span class="token punctuation">|</span>max<span class="token punctuation">:</span><span class="token number">2000</span>
        <span class="token key atrule">tags</span><span class="token punctuation">:</span> step2
</code></pre></div><p>Each step validates only the fields tagged for that step, so a required field on a later step never prevents an earlier step from being saved.</p><div class="custom-block tip"><p>When your site runs behind a proxy or CDN, configure the <a href="./../../setup/configuration.html">trusted proxy settings</a> so the correct visitor IP address is captured.</p></div><h3 id="record-titles"><a href="#record-titles" class="header-anchor">#</a> Record Titles</h3><p>Submissions generate their record title automatically since there is no title field presented to the visitor. Use the <code>titleTemplate</code> property to build the title from the submitted field values, where every field is available as a Twig variable, along with a <code>record</code> variable for accessing related records.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">submission</span><span class="token punctuation">:</span>
    <span class="token key atrule">titleTemplate</span><span class="token punctuation">:</span> <span class="token string">&#39;{{ author_name }} on {{ record.post.title }}&#39;</span>
</code></pre></div><p>When no template is configured, the title falls back to the first available value from the <code>name</code>, <code>subject</code>, <code>author_name</code>, <code>full_name</code> or <code>email</code> fields, otherwise a random reference is generated, for example, <strong>Submission #GNNWPWFK</strong>.</p><h3 id="email-notifications"><a href="#email-notifications" class="header-anchor">#</a> Email Notifications</h3><p>Use the <code>notifyGroup</code> property to send an email notification to an <a href="./../../extend/backend/users.html#groups">admin user group</a> every time a submission is received. The value is the group code, found in the admin panel by navigating to <strong>Settings → Team → Manage Groups</strong>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">submission</span><span class="token punctuation">:</span>
    <span class="token key atrule">notifyGroup</span><span class="token punctuation">:</span> contact<span class="token punctuation">-</span>team
</code></pre></div><p>Notifications are sent with the generic <code>tailor:submission-notification</code> mail template, listing the submitted field values with a link to moderate the record in the admin panel. Use the <code>notifyTemplate</code> property to specify a custom <a href="./../../extend/system/sending-mail.html">mail template</a>, where every field is available as a Twig variable, along with the following variables.</p><div class="table"><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><strong>fields</strong></td><td>the submitted field values as an array of <code>label</code> and <code>value</code> pairs.</td></tr><tr><td><strong>title</strong></td><td>the generated record title.</td></tr><tr><td><strong>blueprintName</strong></td><td>the name of the submission blueprint.</td></tr><tr><td><strong>recordUrl</strong></td><td>a link to the record in the admin panel.</td></tr><tr><td><strong>record</strong></td><td>the submission record for accessing related records.</td></tr></tbody></table></div><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">submission</span><span class="token punctuation">:</span>
    <span class="token key atrule">notifyGroup</span><span class="token punctuation">:</span> contact<span class="token punctuation">-</span>team
    <span class="token key atrule">notifyTemplate</span><span class="token punctuation">:</span> blog<span class="token punctuation">:</span>new<span class="token punctuation">-</span>comment
</code></pre></div><p>When the submission contains a valid email address, it is used as the reply-to address for the notification, letting moderators respond directly from their mail client. The address is taken from the <code>email</code> field by default and the <code>notifyReplyTo</code> property can specify a different field name.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">submission</span><span class="token punctuation">:</span>
    <span class="token key atrule">notifyGroup</span><span class="token punctuation">:</span> contact<span class="token punctuation">-</span>team
    <span class="token key atrule">notifyReplyTo</span><span class="token punctuation">:</span> author_email
</code></pre></div><p>Notification failures never lose a submission since the record is saved first, and any mail errors are captured in the event log without interrupting the visitor.</p><h2 id="global"><a href="#global" class="header-anchor">#</a> Global</h2><p>Globals are used to define globally available content for your website. The field values are often used in <a href="./../../cms/themes/layouts.html">CMS layouts</a> and contain settings, such as social networking links.</p><p>The following defines a <strong>Footer Config</strong> global with a Facebook Link (<code>facebook_link</code>) text field.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">handle</span><span class="token punctuation">:</span> Site\\Footer
<span class="token key atrule">type</span><span class="token punctuation">:</span> global
<span class="token key atrule">name</span><span class="token punctuation">:</span> Footer Config

<span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">facebook_link</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Facebook Link
        <span class="token key atrule">type</span><span class="token punctuation">:</span> text
</code></pre></div><p>The following properties are supported by the global blueprint.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>handle</strong></td><td>A meaningful and unique code to identify the entry.</td></tr><tr><td><strong>name</strong></td><td>The label to display when working with this entry.</td></tr><tr><td><strong>fields</strong></td><td>form fields belonging to the group, see <a href="./../../element/form-fields.html">backend form fields</a>.</td></tr><tr><td><strong>multisite</strong></td><td>enables multisite for this entry, supported values: <code>true</code>, <code>false</code>. Default: <code>false</code></td></tr><tr><td><strong>formSize</strong></td><td>the settings form size, supported values: <code>tiny</code>, <code>small</code>, <code>medium</code>, <code>large</code>, <code>huge</code>, <code>giant</code>, <code>adaptive</code>. Default: <code>huge</code>.</td></tr><tr><td><strong>permissions</strong></td><td>customize the permission <code>code</code> and <code>label</code> registered for this blueprint (see <a href="#custom-permissions">Custom Permissions</a>).</td></tr></tbody></table></div><h2 id="mixin"><a href="#mixin" class="header-anchor">#</a> Mixin</h2><p>Mixins are groups of fields that are used to avoid repetition when defining content structures. For example, a Location field may be used in several places, yet we can define it once using a mixin definition.</p><p>The following defines a <strong>Location</strong> collection with Country (<code>country_code</code>) and State (<code>state_code</code>) text fields.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">handle</span><span class="token punctuation">:</span> Fields\\Location
<span class="token key atrule">type</span><span class="token punctuation">:</span> mixin
<span class="token key atrule">name</span><span class="token punctuation">:</span> Location

<span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">country_code</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Country
        <span class="token key atrule">type</span><span class="token punctuation">:</span> text

    <span class="token key atrule">state_code</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> State
        <span class="token key atrule">type</span><span class="token punctuation">:</span> text
</code></pre></div><p>The following properties are supported by the mixin blueprint.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>handle</strong></td><td>A meaningful and unique code to identify the entry.</td></tr><tr><td><strong>name</strong></td><td>The label to display when working with this entry.</td></tr><tr><td><strong>fields</strong></td><td>form fields belonging to the group, see <a href="./../../element/form-fields.html">backend form fields</a>.</td></tr></tbody></table></div><div class="custom-block tip"><p>Consider prefixing the mixin file and field names with an underscore (_) to make the blueprint type easy to find. For example: <code>_location_fields.yaml</code></p></div><h3 id="using-the-mixin"><a href="#using-the-mixin" class="header-anchor">#</a> Using the Mixin</h3><p>To include these fields in your entries, like any other form field, use the <code>type</code> of <strong>mixin</strong> and reference the UUID or handle in the <code>source</code> property.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">_location_fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> mixin
    <span class="token key atrule">source</span><span class="token punctuation">:</span> Fields\\Location
</code></pre></div><p>See the <a href="./../../element/content/field-mixin.html">Mixin field</a> for more information on using mixins.</p><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../../element/content/field-mixin.html">Mixin Content Field</a></li></ul></div>`,106))])}const b=o(c,[["render",d]]);export{f as __pageData,b as default};
